fn tri(n: usize, m: usize, k: i32) -> Vec<Vec<f64>> {
    let mut matrix = Vec::with_capacity(n);
    for i in 0..n {
        let mut row = Vec::with_capacity(m);
        let limit = i as i32 + k;
        for j in 0..m {
            // j <= i + k, converting j to i32 for comparison
            if (j as i32) <= limit {
                row.push(1.0);
            } else {
                row.push(0.0);
            }
        }
        matrix.push(row);
    }
    matrix
}